"""External-study and history presentation; all results come from backend records."""
PANEL='''<section class="panel" id="c10-study" style="margin-top:24px"><h2>Cycle 10 · External games and historical evidence</h2><p>Inspect the independent corpus, compare frozen and experimental models, and replay supplied game events. Empirical calibration is displayed separately from native strength and confidence.</p><div class="c10-grid"><div><label for="c10-section">Research report</label><select id="c10-section"><option value="summary">External generalization</option><option value="provenance">Source provenance and licenses</option><option value="failures">Failure families</option><option value="calibration">Calibration under distribution shift</option><option value="comparisons">Adaptation results</option><option value="dependence">Evidence dependence</option><option value="temporal">Temporal controls</option><option value="performance">Performance comparison</option><option value="identity">Model and runtime identity</option><option value="architecture">Native architecture decision</option></select></div><div><label for="c10-arm">Recorded evaluation</label><select id="c10-arm"><option value="frozen">Frozen C8 · FEN only</option><option value="small">Small adaptation · experimental</option><option value="large">Large adaptation · experimental</option><option value="temporal">Frozen C8 · supplied PGN history</option></select></div></div><div class="summary"><button type="button" id="c10-load">Load external report</button><button type="button" id="c10-export">Export external JSON</button></div><p id="c10-status" role="status">No external report loaded.</p><label for="c10-population">Candidate population</label><select id="c10-population"><option value="complete">Complete candidate set</option><option value="in_board">In-board candidates only</option></select><div style="overflow:auto;max-width:100%"><table id="c10-table" style="width:100%;min-width:680px;text-align:left"><thead><tr><th>Cohort / source</th><th>Candidates</th><th>Precision</th><th>Recall</th><th>Exact sets</th><th>False legal</th><th>False illegal</th><th>Unknown</th></tr></thead><tbody></tbody></table></div><label for="c10-case">Recorded unresolved candidate</label><select id="c10-case" disabled><option>Load failure families first</option></select><div class="summary"><button type="button" id="c10-proof" disabled>View external native proof</button><button type="button" id="c10-use" disabled>Open this candidate</button></div><details><summary>Historical game replay</summary><p>Published move records supply observed events. Initial standard-position metadata is explicitly trusted; historical legality remains unverified by the production replayer.</p><button type="button" id="c10-games">Load source games</button><label for="c10-game">Published game record</label><select id="c10-game" disabled><option>Load source games first</option></select><label for="c10-ply">Replay through ply</label><input id="c10-ply" type="number" min="0" value="12"><div class="summary"><button type="button" id="c10-replay" disabled>Replay supplied events</button><button type="button" id="c10-history-use" disabled>Use replayed history</button></div><pre id="c10-history">No game history replayed.</pre></details><details><summary>Temporal evidence-removal demonstrations</summary><label for="c10-control-index">Demonstration index (0–20)</label><input id="c10-control-index" type="number" min="0" max="20" value="0"><button type="button" id="c10-control">Load temporal counterfactual</button></details><details><summary>Compare experimental adaptations</summary><p>The comparison uses the position, move, history and inference mode above. “Verified default” selects operational mode for this explicit research comparison. The frozen model remains selected.</p><button type="button" id="c10-compare">Compare frozen, small and large models</button></details><pre id="c10-detail"></pre></section>'''
LIVE='''<details open><summary>External calibration and native identity</summary><p>Raw PLN values and empirical frequencies are distinct diagnostics. Experimental adaptations have no validated calibration mapping.</p><pre id="c10-live"></pre></details>'''
SCRIPT=r'''
let c10Current=null,c10Metrics=null,c10Failure=null,c10History=null;
function c10Render(){const body=document.querySelector('#c10-table tbody');body.replaceChildren();if(!c10Metrics)return;for(const [name,group] of Object.entries(c10Metrics)){const m=group[$('c10-population').value];if(!m)continue;const tr=document.createElement('tr');for(const value of [name,m.candidates,c9Pct(m.precision),c9Pct(m.recall),m.exact_positions+'/'+m.positions,m.false_positive,m.false_illegal,m.unknown]){const td=document.createElement('td');td.style.padding='8px';td.textContent=value;tr.append(td)}body.append(tr)}}
async function c10Fetch(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error);if(d.available===false)throw Error(d.reason);return d}
async function c10Action(button,fn){button.disabled=true;$('c10-status').textContent='Loading…';try{await fn()}catch(e){$('c10-status').textContent='Error: '+e.message}finally{button.disabled=false}}
$('c10-load').addEventListener('click',()=>c10Action($('c10-load'),async()=>{const section=$('c10-section').value;const d=await c10Fetch('/cycle10?section='+section+'&arm='+$('c10-arm').value);c10Current=d;$('c10-detail').textContent=JSON.stringify(d,null,2);if(section==='summary'){c10Metrics=d.data;c10Render()}if(section==='failures'){c10Failure=null;$('c10-use').disabled=true;$('c10-case').replaceChildren();for(const item of d.data.entries){const option=document.createElement('option');option.value=item.index;option.textContent=item.fixture+' '+item.move+' · '+item.kind+' · '+item.categories.join(', ');$('c10-case').append(option)}$('c10-case').disabled=!d.data.entries.length;$('c10-proof').disabled=!d.data.entries.length}$('c10-status').textContent='Recorded '+section+' · '+d.arm+' · '+d.sha256}));
$('c10-population').addEventListener('change',c10Render);
$('c10-arm').addEventListener('change',()=>{c10Failure=null;c10Metrics=null;c10Render();$('c10-use').disabled=true;$('c10-proof').disabled=true;$('c10-case').disabled=true;$('c10-detail').textContent='';$('c10-status').textContent='Load a report for the selected evaluation.'});
$('c10-case').addEventListener('change',()=>{c10Failure=null;$('c10-use').disabled=true});
$('c10-proof').addEventListener('click',()=>c10Action($('c10-proof'),async()=>{const d=await c10Fetch('/cycle10-proof?index='+encodeURIComponent($('c10-case').value)+'&arm='+$('c10-arm').value);c10Current=d;c10Failure=d.data;$('c10-detail').textContent=JSON.stringify(d,null,2);$('c10-use').disabled=!d.data.row;$('c10-status').textContent='Native proof, hypotheses and source evidence loaded.'}));
$('c10-use').addEventListener('click',()=>c10Action($('c10-use'),async()=>{if(!c10Failure||!c10Failure.row)return;const r=c10Failure.row;$('fen').value=r.fen;$('move').value=r.move;$('model').value=['small','large'].includes($('c10-arm').value)?'C10-'+$('c10-arm').value:'C8-default';$('mode').value='operational';$('compare-models').checked=false;$('temporal-mode').value='fen-only';$('history').value='{}';if($('c10-arm').value==='temporal'){const f=c10Failure.fixture;c10History=await c10Fetch('/cycle10-game?game='+encodeURIComponent(f.source_game)+'&ply='+f.ply);$('temporal-mode').value='event-backed';$('history').value=JSON.stringify(c10History.legacy_evidence,null,2)}$('status').textContent='Recorded candidate loaded with its evaluation history policy. Run native inference to inspect it.';$('c10-status').textContent='Candidate and evidence policy loaded.';board(r.fen,r.move);$('form').scrollIntoView()}));
$('c10-games').addEventListener('click',()=>c10Action($('c10-games'),async()=>{const d=await c10Fetch('/cycle10-games');c10Current=d;$('c10-game').replaceChildren();for(const g of d.games){const o=document.createElement('option');o.value=g.id;o.dataset.plies=g.plies;o.textContent=g.source+' · '+g.headers.White+' / '+g.headers.Black+' · '+g.plies+' plies';$('c10-game').append(o)}$('c10-game').disabled=false;$('c10-replay').disabled=false;$('c10-status').textContent=d.games.length+' published game records loaded.'}));
$('c10-game').addEventListener('change',()=>{c10History=null;$('c10-history-use').disabled=true;const limit=Number($('c10-game').selectedOptions[0].dataset.plies);$('c10-ply').max=limit;$('c10-ply').value=Math.min(Number($('c10-ply').value),limit)});
$('c10-ply').addEventListener('input',()=>{c10History=null;$('c10-history-use').disabled=true});
$('c10-replay').addEventListener('click',()=>c10Action($('c10-replay'),async()=>{const d=await c10Fetch('/cycle10-game?game='+encodeURIComponent($('c10-game').value)+'&ply='+encodeURIComponent($('c10-ply').value));c10Current=d;c10History=d;$('c10-history').textContent=JSON.stringify(d,null,2);$('c10-history-use').disabled=false;$('c10-status').textContent=d.events.length+' supplied events · '+d.status+' · historical legality '+d.historical_legality}));
$('c10-history-use').addEventListener('click',()=>{if(!c10History)return;$('fen').value=c10History.resulting_fen;$('history').value=JSON.stringify(c10History.legacy_evidence,null,2);$('temporal-mode').value='event-backed';$('model').value='C8-default';$('mode').value='operational';$('move').value='';$('compare-models').checked=false;board(c10History.resulting_fen);$('status').textContent='Supplied history loaded. Choose a move or run the complete candidate set.';$('form').scrollIntoView()});
$('c10-control').addEventListener('click',()=>c10Action($('c10-control'),async()=>{const d=await c10Fetch('/cycle10-control?index='+encodeURIComponent($('c10-control-index').value));c10Current=d;$('c10-detail').textContent=JSON.stringify(d,null,2);$('c10-status').textContent='Counterfactual '+d.data.id+' · source events, native proofs and removal control loaded.'}));
$('c10-compare').addEventListener('click',()=>c10Action($('c10-compare'),async()=>{const d=await c10Fetch('/cycle10-compare',{fen:$('fen').value,move:$('move').value.trim(),mode:$('mode').value==='default'?'operational':$('mode').value,temporal_mode:$('temporal-mode').value,temporal_evidence:JSON.parse($('history').value),max_invocations:Number($('max-invocations').value)});c10Current=d;current=d;comparisonTable(d.comparisons);show(d.comparisons.frozen.candidate);$('raw').textContent=JSON.stringify(d,null,2);$('model-comparison').textContent=JSON.stringify(d.differences,null,2);$('c10-detail').textContent=JSON.stringify(d,null,2);$('c10-status').textContent='Three models compared in '+d.selected_mode+' mode. Frozen C8 remains selected.'}));
$('c10-export').addEventListener('click',()=>{if(!c10Current)return;const u=URL.createObjectURL(new Blob([JSON.stringify(c10Current,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='pln-chess-cycle10-research.json';a.click();URL.revokeObjectURL(u)});
'''


def extend(html):
    html=html.replace('</style>','.c10-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}#c10-study{overflow-wrap:anywhere}#c10-study select{min-width:0;max-width:100%}#c10-status{overflow-wrap:anywhere}@media(max-width:760px){.c10-grid{grid-template-columns:minmax(0,1fr)}}\n</style>')
    html=html.replace('</main>',PANEL+'</main>')
    html=html.replace('<details><summary>Runtime, budget, and raw result</summary>',LIVE+'<details><summary>Runtime, budget, and raw result</summary>')
    html=html.replace('function show(c){',"function show(c){$('c10-live').textContent=JSON.stringify({raw_native_stv:c.raw_stv,legal_move_truth_value:c.legal_move_truth_value,classification:c.classification,proof_status:c.proof_status,evidence_ids:c.evidence_ids,dependence_groups:c.dependence_groups,history_status:c.temporal_evidence&&c.temporal_evidence.status,model_version:c.model_version,runtime_version:c.runtime_version,calibration:c.external_diagnostics||{available:false}},null,2);")
    html=html.replace("'c9-live']","'c9-live','c10-live']")
    html=html.replace('<option value="C8-default">C8 · Verified default</option>','<option value="C8-default">C8 · Verified default</option><option value="C10-small">C10 · Small external adaptation (experimental)</option><option value="C10-large">C10 · Large external adaptation (experimental)</option>')
    return html.replace('</script>',SCRIPT+'</script>')
